def page(title, description, body,active='',scripts='',landing=False):
 head=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#091e3b"><title>{html.escape(title)} | Tintas Mastercolor</title><meta name="description" content="{html.escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title,quote=True)} | Tintas Mastercolor"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:image" content="assets/imagens/hero/hero-sala.webp"><link rel="icon" type="image/svg+xml" href="assets/imagens/logo/favicon.svg"><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/responsive.css"></head><body>'''
 foot='''<script src="assets/js/config.js"></script><script src="assets/js/produtos-data.js"></script><script defer src="assets/js/main.js"></script>'''+scripts+'</body></html>'
 return head+header(active)+body+footer()+foot

